export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

const PROCESSING_FEE = 5;
const HUNDRED_PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_LEVEL = 5;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;

const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / HUNDRED_PERCENT;
}

/** Premiums are rounded up to whole G, in the MHPCO's favor. */
function roundPremiumInMhpcoFavor(premium: number): number {
  return Math.ceil(premium);
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  return counts;
}

function basePremiumOfAlikeComponents(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function basePremiumOfAlike(type: string, count: number): number {
  if (COMPONENT_TYPES.has(type)) return basePremiumOfAlikeComponents(count);
  return count * MAIN_ITEM_BASE_PREMIUMS[type];
}

function policyBasePremiumOf(items: Item[]): number {
  let sum = 0;
  for (const [type, count] of countByType(items)) sum += basePremiumOfAlike(type, count);
  return sum;
}

interface ItemRiskSurcharge {
  appliesTo: (item: Item) => boolean;
  percent: number;
}

/** Item-specific modifiers: each applies to the base premium of the affected item only. */
const ITEM_RISK_SURCHARGES: ItemRiskSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
  { appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
];

function itemRiskSurchargesOf(items: Item[]): number {
  let sum = 0;
  for (const item of items)
    for (const surcharge of ITEM_RISK_SURCHARGES)
      if (surcharge.appliesTo(item)) sum += percentOf(MAIN_ITEM_BASE_PREMIUMS[item.type], surcharge.percent);
  return sum;
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function quote(items: Item[], customer: Customer, isFollowUpContract: boolean): QuoteResult {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge = percentOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  const loyaltyDiscount = isLongStandingCustomer(customer) ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT) : 0;
  const followUpDiscount = isFollowUpContract ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT) : 0;
  const premium =
    policyBasePremium +
    itemRiskSurchargesOf(items) +
    firstInsuranceSurcharge -
    loyaltyDiscount -
    followUpDiscount +
    PROCESSING_FEE;
  return { premium: roundPremiumInMhpcoFavor(premium) };
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  let contractsSoFar = 0;
  const results = scenario.steps.map((step) => {
    const result = quote(step.op === "quote" ? step.items : [], scenario.customer, contractsSoFar > 0);
    contractsSoFar++;
    return result;
  });
  return { results };
}
import { describe, expect, it } from "vitest";
import { runScenario, type Item, type QuoteResult } from "./claimOffice.js";

function quotePremium(items: Item[], yearsWithMHPCO = 0): number {
  const { results } = runScenario({ customer: { yearsWithMHPCO }, steps: [{ op: "quote", items }] });
  return (results[0] as QuoteResult).premium;
}

function alikeComponents(count: number, type: string): Item[] {
  return Array.from({ length: count }, () => ({ type }));
}

// Reading adopted for premiums: every quote is a first insurance (+10 % of the
// policy base premium); follow-up contracts are later `quote` steps in the same
// scenario. Derived expected premiums show their arithmetic in the description.

describe("quote", () => {
  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(quotePremium([])).toBe(5);
  });
  it("plain sword, newcomer -> premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 3, cursed: false }])).toBe(115);
  });
  it("plain amulet, newcomer -> premium 71 G (60 + 6 + 5)", () => {
    expect(quotePremium([{ type: "amulet", material: "silver", enchantment: 2, cursed: false }])).toBe(71);
  });
  it("plain staff, newcomer -> premium 93 G (80 + 8 + 5)", () => {
    expect(quotePremium([{ type: "staff", material: "oak", enchantment: 2, cursed: false }])).toBe(93);
  });
  it("plain potion, newcomer -> premium 49 G (40 + 4 + 5)", () => {
    expect(quotePremium([{ type: "potion", material: "glass", enchantment: 1, cursed: false }])).toBe(49);
  });
  it("1 rune, newcomer -> premium 33 G (25 + 2.5 + 5 = 32.5, rounded up in MHPCO's favor)", () => {
    expect(quotePremium([{ type: "rune" }])).toBe(33);
  });
  it("1 moonstone, newcomer -> premium 33 G (25 + 2.5 + 5 = 32.5, rounded up)", () => {
    expect(quotePremium([{ type: "moonstone" }])).toBe(33);
  });
  it("2 runes -> base 50 G -> premium 60 G (50 + 5 + 5)", () => {
    expect(quotePremium(alikeComponents(2, "rune"))).toBe(60);
  });
  it("3 runes -> block base 60 G -> premium 71 G (60 + 6 + 5)", () => {
    expect(quotePremium(alikeComponents(3, "rune"))).toBe(71);
  });
  it("4 runes -> no block, base 100 G -> premium 115 G", () => {
    expect(quotePremium(alikeComponents(4, "rune"))).toBe(115);
  });
  it("7 runes -> base 175 G -> premium 198 G (175 + 17.5 + 5 = 197.5, rounded up)", () => {
    expect(quotePremium(alikeComponents(7, "rune"))).toBe(198);
  });
  it("2 runes + 1 moonstone -> no block (different types), base 75 G -> premium 88 G (87.5 rounded up)", () => {
    expect(quotePremium([...alikeComponents(2, "rune"), { type: "moonstone" }])).toBe(88);
  });
  it("3 moonstones -> block base 60 G -> premium 71 G", () => {
    expect(quotePremium(alikeComponents(3, "moonstone"))).toBe(71);
  });
  it("3 runes + 3 moonstones -> two blocks, base 120 G -> premium 137 G (120 + 12 + 5)", () => {
    expect(quotePremium([...alikeComponents(3, "rune"), ...alikeComponents(3, "moonstone")])).toBe(137);
  });
  it("cursed sword (steel, enchantment 3), newcomer -> premium 165 G (100 + 50 curse + 10 + 5)", () => {
    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
  });
  it("cursed sword + plain amulet -> curse on the sword only: 160 + 50 + 16 first insurance + 5 -> premium 231 G", () => {
    expect(
      quotePremium([
        { type: "sword", material: "steel", enchantment: 3, cursed: true },
        { type: "amulet", material: "silver", enchantment: 2, cursed: false },
      ]),
    ).toBe(231);
  });
  it("sword with enchantment 4, not cursed -> no high-enchantment surcharge -> premium 115 G", () => {
    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 4, cursed: false }])).toBe(115);
  });
  it("sword with exactly enchantment 5 -> high-enchantment surcharge -> premium 145 G (100 + 30 + 10 + 5)", () => {
    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 5, cursed: false }])).toBe(145);
  });
  it("cursed sword with enchantment 5 -> both surcharges -> premium 195 G (100 + 50 + 30 + 10 + 5)", () => {
    expect(quotePremium([{ type: "sword", material: "steel", enchantment: 5, cursed: true }])).toBe(195);
  });
  it("customer with 1 year -> no loyalty discount; plain sword -> premium 115 G", () => {
# MHPCO Claim Office Kata

## Setting

You are building the policy management system for the **Most Honorable
Privileged Claims Office for Magical Risks and Cursed Items** (MHPCO),
an old-fashioned insurance institution that covers magical items —
swords, amulets, staves, potions, and components such as runes and
moonstones. The MHPCO is bureaucratic, slightly stingy, and proud of
its venerable traditions.

## Feature

The system supports two operations: **quote** computes the premium for
a list of items a customer wishes to insure, and **claim** processes a
damage report against an existing policy.

## Rules

### Item values and base premiums

Each main item has an insurance value and a base premium according to
the MHPCO price list:

- Sword: 1000 G insurance value, 100 G base premium
- Amulet: 600 G / 60 G
- Staff: 800 G / 80 G
- Potion: 400 G / 40 G

Components — for example runes and moonstones — are insured at 250 G
each, with a base premium of 25 G per component. A building block of
3 alike components is offered at a special base premium of 60 G.

### Premium modifiers

- Cursed items add a 50 % risk surcharge.
- Highly enchanted items (enchantment level ≥ 5) add a 30 % risk
  surcharge.
- Long-standing customers (≥ 2 years of business with MHPCO) receive a
  20 % loyalty discount.
- A first insurance carries a 10 % initial assessment surcharge.
- Customers receive a 15 % discount on each contract after their first.
- A 5 G processing fee is added to every premium.

All amounts are rounded to whole G in the MHPCO's favor.

### Claim processing

A deductible of 100 G applies per damage event. The total payout per
policy is capped at twice the insurance sum.

- Damage to items with enchantment level ≥ 8 is reimbursed at 50 % of
  the damage amount.
- Damage to items made of dragon material is fully reimbursed.

## Examples

The examples below illustrate single rules in isolation. Values shown
are base premiums or raw payout amounts before integration with other
modifiers, unless stated otherwise.

### Building block of 3 alike components

- 2 runes → 50 G base premium
- 3 runes → 60 G base premium (block applies)
- 4 runes → 100 G base premium (no block — block requires exactly 3)
- 7 runes → 175 G base premium

### "Alike" components

> ❓ Hmm — "alike" components: does that mean exactly the same type,
> or just the same family (rune-y, gemstone-y)?

- 2 runes + 1 moonstone → 75 G base premium (no block: different types)
- 3 runes + 3 moonstones → 120 G base premium (two separate blocks)

### Modifier scope on multi-item policies

> ❓ A policy with several items: does the cursed surcharge apply to
> the whole policy, or just to the cursed item?

